INSERT INTO `blog_posts` (`id`, `title`, `slug`, `image_path`, `excerpt`, `content_blocks`, `author_name`, `author_designation`, `is_published`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'The Future of IT Asset Disposition: Why Circular Economy Matters', 'the-future-of-it-asset-disposition-why-circular-economy-matters', 'blog_images/Y3gjM7ve0gjuQmndWfglcYL1AdDjeegV8s8pOKDR.jpg', 'Discover how modern companies are turning old IT equipment into a strategic advantage by focusing on responsible disposal and data security.', '[{\"type\":\"heading\",\"size\":null,\"alignment\":null,\"content\":\"Introduction to ITAD\"},{\"type\":\"paragraph\",\"size\":null,\"alignment\":null,\"content\":\"IT Asset Disposition (ITAD) is no longer just about throwing away old computers. It is a strategic process that ensures data security, maximizes return on investment, and supports environmental sustainability.\"},{\"type\":\"subheading\",\"size\":null,\"alignment\":null,\"content\":\"Why Data Security is Paramount\"},{\"type\":\"paragraph\",\"size\":null,\"alignment\":null,\"content\":\"Every hard drive contains sensitive data. Proper ITAD ensures that this data is securely wiped or physically destroyed according to NIST standards before the equipment leaves your premises.\"},{\"type\":\"image\",\"size\":\"w-1\\/2\",\"alignment\":\"mx-auto\",\"image_path\":\"blog_content_images\\/dor7mxE4iV6U4rDzvHkJ8ZDuVi7Z5htxYr7GxB4v.jpg\",\"content\":null},{\"type\":\"heading\",\"size\":null,\"alignment\":null,\"content\":\"The Environmental Impact\"},{\"type\":\"paragraph\",\"size\":null,\"alignment\":null,\"content\":\"By refurbishing and remarketing functional equipment, we reduce e-waste and prevent harmful materials from entering landfills. This aligns with global ESG (Environmental, Social, and Governance) goals.\"},{\"type\":\"subheading\",\"size\":null,\"alignment\":null,\"content\":\"\"}]', 'Deepak Kumar', NULL, 1, '2026-10-22 12:04:48', '2026-10-22 12:04:48', '2026-10-22 14:23:59'),
(2, 'test post', 'test-post', NULL, 'A short introduction to responsible IT asset lifecycle planning.', '[{\"type\":\"html\",\"content\":\"<p>Retrotech helps organizations manage IT assets responsibly through secure data handling, reuse, and practical lifecycle planning. A clear process can support stronger oversight, reduce waste, and make each project easier to coordinate.<\\/p>\"}]', 'Admin', NULL, 1, '2026-10-23 08:25:31', '2026-10-23 07:36:55', '2026-10-23 08:25:31'),
(3, 'Retrotech Blog Editor Verification', 'retrotech-blog-editor-verification', NULL, 'A brief sample post to verify rich text editing and publishing.', '[{\"type\":\"html\",\"content\":\"<p>Welcome to our test article. CKEditor is accepting content. Edit screen verified. ksd lkajsdf ajdldksfjalk adsdfalkdjfaldsf\\u00a0<\\/p>\"}]', 'Admin', NULL, 1, '2026-10-23 08:25:13', '2026-10-23 07:44:26', '2026-10-23 11:41:28'),
(4, 'Diwali', 'diwali', NULL, 'jhbnhih', '[{\"type\":\"html\",\"content\":\"<p>rom Wikipedia, the free encyclopedia<\\/p><figure class=\\\"table\\\"><table><thead><tr><th><strong>Diwali<\\/strong><\\/th><\\/tr><\\/thead><tbody><tr><td><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Rangoli\\\">Rangoli<\\/a> decorations, made using coloured fine powder or sand, are popular during Diwal<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>\\u00a0<\\/p><p><i>\\\"Deepawali\\\" and \\\"Dipawali\\\" redirect here. For other uses, see <\\/i><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Deepavali_(disambiguation)\\\"><i>Deepavali (disambiguation)<\\/i><\\/a><i>.<\\/i><\\/p><figure class=\\\"table\\\"><table><thead><tr><th><strong>Diwali<\\/strong><\\/th><th>\\u00a0<\\/th><\\/tr><\\/thead><tbody><tr><td><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Rangoli\\\">Rangoli<\\/a> decorations, made using coloured fine powder or sand, are popular during Diwali.<\\/td><td>\\u00a0<\\/td><\\/tr><tr><td>Official name<\\/td><td><i>D\\u012bp\\u0101val\\u012b<\\/i><\\/td><\\/tr><tr><td>Also called<\\/td><td>Deepavali, Deepawali<\\/td><\\/tr><tr><td>Observed\\u00a0by<\\/td><td><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindus\\\">Hindus<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Jains\\\">Jains<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Sikhs\\\">Sikhs<\\/a>,<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Diwali#cite_note-1\\\">[1]<\\/a> some <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Buddhism\\\">Buddhists<\\/a> (notably <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Newar_Buddhism\\\">Newar Buddhists<\\/a><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Diwali#cite_note-diwaliBuddhist-2\\\">[2]<\\/a>)<\\/td><\\/tr><tr><td>Type<\\/td><td>Religious, cultural, seasonal<\\/td><\\/tr><tr><td>Significance<\\/td><td><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Diwali#Religious_significance\\\"><i>See below<\\/i><\\/a><\\/td><\\/tr><tr><td>Celebrations<\\/td><td><ul><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Diya_(light)\\\">Diya<\\/a> lighting<\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Puja_(Hinduism)\\\"><i>puja<\\/i><\\/a> (worship and prayer)<\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hukka_Paati\\\"><i>Hukka Paati<\\/i><\\/a> in <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Mithila_region\\\">Mithila region<\\/a><\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Homa_(ritual)\\\"><i>havan<\\/i><\\/a> (fire offering)<\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Vrata\\\"><i>vrat<\\/i><\\/a> (fasting)<\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/D%C4%81na\\\"><i>d\\u0101na<\\/i><\\/a> (charity)<\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Mel%C4%81\\\"><i>mel\\u0101<\\/i><\\/a> (fairs\\/shows)<\\/li><li>home cleansing and decoration<\\/li><li>fireworks<\\/li><li>gifts<\\/li><li>and partaking in a feast and <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Sweets_from_the_Indian_subcontinent\\\">sweets<\\/a><\\/li><\\/ul><\\/td><\\/tr><tr><td>Begins<\\/td><td><ul><li>Ashwayuja 27 or Ashwayuja 28 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindu_calendar#amanta\\\">amanta<\\/a> tradition)<\\/li><li>Kartika 12 or Kartika 13 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindu_calendar#purnimanta\\\">purnimanta<\\/a> tradition)<\\/li><\\/ul><\\/td><\\/tr><tr><td>Ends<\\/td><td><ul><li>Kartika 2 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindu_calendar#amanta\\\">amanta<\\/a> tradition)<\\/li><li>Kartika 17 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindu_calendar#purnimanta\\\">purnimanta<\\/a> tradition)<\\/li><\\/ul><\\/td><\\/tr><tr><td>Date<\\/td><td>Ashvin Krishna Trayodashi, Ashvin Krishna Chaturdashi, Ashvin Amavasya, Kartik Shukla Pratipada, Kartik Shukla Dwitiya<\\/td><\\/tr><tr><td>2026\\u00a0date<\\/td><td><p>November<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Diwali#cite_note-3\\\">[3]<\\/a><\\/p><ul><li>6 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Dhanteras\\\">Dhanteras<\\/a>\\/Yama Deepam\\/Kwah Puja\\/Kaag Tihar)<\\/li><li>7 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Naraka_Chaturdashi\\\">Naraka Chaturdashi<\\/a>\\/Kali Chaudas\\/Hanuman Puja\\/Chhoti Diwali\\/Khicha Puja\\/<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Kukur_Tihar\\\">Kukur Tihar<\\/a>)<\\/li><li>8 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Lakshmi_Puja\\\">Lakshmi Puja<\\/a>\\/<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Kali_Puja\\\">Kali Puja<\\/a>\\/Sharda Puja\\/Kedar Gauri Vrat\\/Sa Puja\\/Gai Tihar)<\\/li><li>9 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Govardhan_Puja\\\">Govardhan Puja<\\/a>\\/<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Balipratipada\\\">Balipratipada<\\/a>\\/<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Mha_Puja\\\">Mha Puja<\\/a>\\/Goru Puja)<\\/li><li>10 (<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Bhai_Dooj\\\">Bhai Dooj<\\/a>\\/<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Vishwakarma_Puja\\\">Vishwakarma Puja<\\/a>\\/<a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Indian_New_Year\'s_days\\\">Gujarati New Year<\\/a>\\/Kija Puja)<\\/li><\\/ul><\\/td><\\/tr><tr><td>2027\\u00a0date<\\/td><td>29 October 2027<\\/td><\\/tr><tr><td>2028\\u00a0date<\\/td><td>17 October 2028<\\/td><\\/tr><tr><td>Duration<\\/td><td>5 or 6 days (regional variations)<\\/td><\\/tr><tr><td>Frequency<\\/td><td>Annual<\\/td><\\/tr><tr><td>Related\\u00a0to<\\/td><td><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Diwali_(Jainism)\\\">Diwali (Jainism)<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Bandi_Chhor_Divas\\\">Bandi Chhor Divas<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Tihar_(festival)\\\">Tihar<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Swanti_(festival)\\\">Swanti<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Sohrai\\\">Sohrai<\\/a>, <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Bandna\\\">Bandna<\\/a><\\/td><\\/tr><\\/tbody><\\/table><\\/figure><figure class=\\\"table\\\"><table><thead><tr><th><strong>Explanatory note<br>on Hindu festival dates<\\/strong><\\/th><\\/tr><\\/thead><tbody><tr><td><p>The <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Astronomical_basis_of_the_Hindu_calendar\\\">Hindu calendar<\\/a> is lunisolar but most festival dates are specified using the lunar portion of the calendar. A lunar day is uniquely identified by three calendar elements: <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Astronomical_basis_of_the_Hindu_calendar#chandramasa\\\"><i>m\\u0101sa<\\/i><\\/a> (lunar month), <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Astronomical_basis_of_the_Hindu_calendar#paksha\\\"><i>pak\\u1e63a<\\/i><\\/a> (lunar fortnight) and <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Astronomical_basis_of_the_Hindu_calendar#tithi\\\"><i>tithi<\\/i><\\/a> (lunar day).<\\/p><p>Furthermore, when specifying the masa, one of two traditions are applicable, viz. <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindu_calendar#amanta\\\"><i>am\\u0101nta<\\/i><\\/a> \\/ <a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Hindu_calendar#purnimanta\\\"><i>p\\u016br\\u1e47im\\u0101nta<\\/i><\\/a>. If a festival falls in the waning phase of the moon, these two traditions identify the same lunar day as falling in two different (but successive) masa.<\\/p><p>A lunar year is shorter than a solar year by about eleven days. As a result, most Hindu festivals occur on different days in successive years on the Gregorian calendar.<\\/p><\\/td><\\/tr><tr><td><ul><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Template:Hindu_festival_date_info\\\">v<\\/a><\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Template_talk:Hindu_festival_date_info\\\">t<\\/a><\\/li><li><a href=\\\"https:\\/\\/en.wikipedia.org\\/wiki\\/Special:EditPage\\/Template:Hindu_festival_date_info\\\"